//! Recursive-descent parser from tokens to [`Expression`] trees.

use crate::error::{Error, Result};
use crate::expressions::*;
use crate::guard::{
    enforce_ast, enforce_parser_token_stats, enforce_parser_tokens, is_guard_error,
    ComplexityGuardOptions, TokenGuardStats,
};
use crate::tokens::{ParserToken, Span, Token, TokenType};
use std::collections::{HashMap, HashSet};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, LazyLock, OnceLock};

/// MySQL table options and the TiDB options among them.
type MySqlTableOptions = (Vec<(String, String)>, Vec<TiDBTableOption>);

/// The modifiers written before `VIEW` in `CREATE ... VIEW`.
struct ViewModifiers {
    or_replace: bool,
    or_alter: bool,
    materialized: bool,
    temporary: bool,
    algorithm: Option<String>,
    definer: Option<String>,
    security: Option<FunctionSecurity>,
    secure: bool,
}

/// Budget shared by the parsers of one parse, fragments included; atomic to stay Send and Sync.
#[derive(Default)]
struct ParserRecursion {
    depth: AtomicUsize,
    failure: OnceLock<(usize, usize, Span)>,
}

impl ParserRecursion {
    fn error(&self) -> Option<Error> {
        self.failure.get().map(|(actual, limit, span)| {
            Error::parse(
                format!("E_GUARD_PARSER_DEPTH_EXCEEDED: value {actual} exceeds configured limit {limit}"),
                span.line, span.column, span.start, span.end,
            )
        })
    }
}

struct ParserDepthScope {
    recursion: Arc<ParserRecursion>,
    levels: usize,
}

impl Drop for ParserDepthScope {
    fn drop(&mut self) {
        self.recursion
            .depth
            .fetch_sub(self.levels, Ordering::Relaxed);
    }
}

